    ld hl, dialogue_line_ptr_table
    add hl, bc
    add hl, bc
    ld e, (hl)
    inc hl
    ld d, (hl)
    ld a, e
    ld (dialogue_text_ptr_l), a
    ld a, d
    ld (dialogue_text_ptr_h), a

    ld hl, dialogue_line_delay_table
