    DB #E6,#61,#91,#81,#41,#41,#64,#41,#E6,#E6,#91,#E9,#E6,#21,#61,#41
    DB #E6,#E6,#61,#61,#64,#41,#21,#41,#61,#21,#E1,#E1,#61,#21,#61,#64
    DB #61,#41,#81,#E1,#E6,#D1,#61,#61,#81,#E6,#81,#E9,#64,#61,#61,#61
    DB #96,#A9,#81,#61,#64,#64,#61,#61,#A9,#96,#E1,#61,#21,#41,#21,#21
    DB #41,#41,#61,#61,#21,#E1,#61,#21,#21,#21,#81,#61,#E6,#E6,#61,#E6
    DB #91,#E6,#E6,#61,#61,#E6,#64,#61,#96,#61,#61,#61,#21,#21,#61,#61
    DB #61,#61,#61,#61,#61,#61,#61,#61,#41,#21,#61,#21,#41,#61,#61,#61
    DB #61,#61,#61,#61,#61,#61,#21,#61,#61,#61,#21,#21,#21,#21,#41,#61
