; Register Contract:
;   Purpose: Wait a configurable number of frames after showing the presentation screen.
;   Inputs:
;     - B = frame count
;   Outputs:
;     - None
;   Clobbers:
;     - AF
;     - B
;   Preserved:
;     - BC
;     - DE
;     - HL
;     - IX
;     - IY
; @mideas:block id=runtime.screens.presentation_wait_frames kind=routine owner=screens
presentation_wait_frames:
    push bc
    ld a, b
    or a
    jr z, .pwf_done
.pwf_loop:
    halt
    djnz .pwf_loop
.pwf_done:
    pop bc
    ret
; @mideas:endblock id=runtime.screens.presentation_wait_frames

; Register Contract:
;   Purpose: Wait for SPACE press and release after showing the presentation screen.
;   Inputs:
;     - None
;   Outputs:
;     - None
;   Clobbers:
;     - AF
;   Preserved:
;     - BC
;     - DE
;     - HL
;     - IX
;     - IY
presentation_wait_for_fire:
.pwff_wait_press:
    halt
    call presentation_read_fire_direct
    or a
    jr z, .pwff_wait_press
.pwff_wait_release:
    halt
    call presentation_read_fire_direct
    or a
    jr nz, .pwff_wait_release
    ret

; Register Contract:
;   Purpose: Read SPACE directly for presentation-screen waits without depending on runtime input tasks.
;   Inputs:
;     - None
;   Outputs:
;     - A = 1 if SPACE pressed, A = 0 otherwise
;   Clobbers:
;     - AF
;   Preserved:
;     - BC
;     - DE
;     - HL
;     - IX
;     - IY
;   Notes:
;     - Uses keyboard matrix row 8 bit 0 (SPACE, active low).
presentation_read_fire_direct:
    ld a, 8
    call FAST_SNSMAT
    bit 0, a
    jr z, .prfd_pressed
    xor a
    ret
.prfd_pressed:
    ld a, 1
    ret

; Register Contract:
;   Purpose: Show the imported fullscreen presentation image in SCREEN 2 without waiting for input.
;   Inputs:
;     - None
;   Outputs:
;     - None
;   Clobbers:
;     - AF
;     - BC
;     - DE
;     - HL
;   Preserved:
;     - IX
;     - IY
;   Notes:
;     - Loads pattern/color banks 0..2 and the 32x24 name table.
;     - MegaROM GameFlow uses this short entrypoint so waits happen after the far-call bank is restored.
show_presentation_screen_image:
    call DISSCR
    ld a, 2
    call CHGMOD
    ; Fullscreen presentation replaces shared gameplay/font tables in VRAM.
    xor a
    ld (vram_cache_tile_patterns_ready), a
    ld (vram_cache_tile_colors_ready), a
    ld (vram_cache_font_ready), a
    ld a, #FF
    ld (current_screen2_tilebank_id), a
    call clear_all_sprites
    call update_sprites_to_vram
    ld hl, PRESENTATION_SCREEN_PATTERNS_B0
    ld de, CHRTBL2
    ld bc, PRESENTATION_SCREEN_PATTERN_B0_SIZE
    call FAST_LDIRVM

    ld hl, PRESENTATION_SCREEN_PATTERNS_B1
    ld de, CHRTBL2 + #800
    ld bc, PRESENTATION_SCREEN_PATTERN_B1_SIZE
    call FAST_LDIRVM

    ld hl, PRESENTATION_SCREEN_PATTERNS_B2
    ld de, CHRTBL2 + #1000
    ld bc, PRESENTATION_SCREEN_PATTERN_B2_SIZE
    call FAST_LDIRVM

    ld hl, PRESENTATION_SCREEN_COLORS_B0
    ld de, CLRTBL2
    ld bc, PRESENTATION_SCREEN_COLOR_B0_SIZE
    call FAST_LDIRVM

    ld hl, PRESENTATION_SCREEN_COLORS_B1
    ld de, CLRTBL2 + #800
    ld bc, PRESENTATION_SCREEN_COLOR_B1_SIZE
    call FAST_LDIRVM

    ld hl, PRESENTATION_SCREEN_COLORS_B2
    ld de, CLRTBL2 + #1000
    ld bc, PRESENTATION_SCREEN_COLOR_B2_SIZE
    call FAST_LDIRVM

    ld hl, PRESENTATION_SCREEN_NAMETBL
    ld de, NAMETBL
    ld bc, PRESENTATION_SCREEN_NAMETBL_SIZE
    call FAST_LDIRVM

    call ENASCR
    ret

; Register Contract:
;   Purpose: Show the imported fullscreen presentation image and apply its configured wait behavior.
;   Inputs:
;     - None
;   Outputs:
;     - None
;   Clobbers:
;     - AF
;     - BC
;     - DE
;     - HL
;   Preserved:
;     - IX
;     - IY
;   Notes:
;     - Legacy entrypoint for direct callers; GameFlow MegaROM handles waits from its own resident-safe path.
show_presentation_screen:
    call show_presentation_screen_image
    call presentation_wait_for_fire
    ret

